12	    }
13	
14	    /**
15	     * 判断一条线段（含端点）是否与轴对齐闭矩形相交。
16	     * 覆盖端点在外而线段穿越矩形内部、以及仅接触边界的情况。
17	     *
18	     * @param ax 端点 A 的 X（米）
19	     * @param ay 端点 A 的 Y（米）
20	     * @param bx 端点 B 的 X（米）
21	     * @param by 端点 B 的 Y（米）
22	     * @param xMin 矩形左边界（含）
23	     * @param yMin 矩形下边界（含）
24	     * @param xMax 矩形右边界（含）
25	     * @param yMax 矩形上边界（含）
26	     * @return true 表示线段有点位于矩形内或边界上
27	     */
28	    public static boolean segmentHitsRectangle(long ax, long ay, long bx, long by,
29	                                               int xMin, int yMin, int xMax, int yMax) {
30	        // 1. 任一端点在闭矩形内（含边界）即命中
31	        if (inRectangle(ax, ay, xMin, yMin, xMax, yMax)
32	                || inRectangle(bx, by, xMin, yMin, xMax, yMax)) {
33	            return true;
34	        }
35	        // 2. 端点均在矩形外：用 Liang-Barsky 直线段裁剪算法，
36	        //    判断线段参数区间 t∈[0,1] 是否与矩形的四个半空间交集非空。
37	        //    端点已在矩形外，交集非空即意味着线段穿过矩形内部或边界，
38	        //    包括仅擦过边界（接触边界）的情况。
39	        long dx = bx - ax;
40	        long dy = by - ay;
41	        double t0 = 0.0d;
42	        double t1 = 1.0d;
43	        // p*x <= q 形式：左 x>=xMin、右 x<=xMax、下 y>=yMin、上 y<=yMax
44	        long[] p = {-dx, dx, -dy, dy};
45	        double[] q = {ax - xMin, xMax - ax, ay - yMin, yMax - ay};
46	        for (int i = 0; i < 4; i++) {
47	            if (p[i] == 0L) {
48	                // 线段与该边界平行且在外侧，则不可能相交
49	                if (q[i] < 0.0d) {
50	                    return false;
51	                }
52	            } else {
53	                double r = q[i] / p[i];
54	                if (p[i] < 0L) {
55	                    if (r > t1) {
56	                        return false;
57	                    }
58	                    if (r > t0) {
59	                        t0 = r;
60	                    }
61	                } else {
62	                    if (r < t0) {
63	                        return false;
64	                    }
65	                    if (r < t1) {
66	                        t1 = r;
67	                    }
68	                }
69	            }
70	        }
71	        return t0 <= t1;
72	    }
