79	     * @param yMin   矩形下边界（含）
80	     * @param xMax   矩形右边界（含）
81	     * @param yMax   矩形上边界（含）
82	     * @return true 表示相交、位于其中或仅接触边界
83	     */
84	    public static boolean polylineHitsRectangle(List<Point> points,
85	                                                int xMin, int yMin, int xMax, int yMax) {
86	        for (int i = 0; i + 1 < points.size(); i++) {
87	            Point a = points.get(i);
88	            Point b = points.get(i + 1);
89	            if (segmentHitsRectangle(a.x(), a.y(), b.x(), b.y(), xMin, yMin, xMax, yMax)) {
90	                return true;
91	            }
92	        }
93	        return false;
94	    }
95	
96	    /**
97	     * 判断点是否位于闭矩形内（含边界）。
98	     */
99	    public static boolean inRectangle(long x, long y,
100	                                      int xMin, int yMin, int xMax, int yMax) {
101	        return x >= xMin && x <= xMax && y >= yMin && y <= yMax;
102	    }
103	}
