                Long start = parts[1].isEmpty() ? null : Long.parseLong(parts[1]);
                Long end = parts[2].isEmpty() ? null : Long.parseLong(parts[2]);
                windows.add(new ZoneWindow(parts[0], start, end));
            }
        }
        return windows;
    }
