        createHitZone("zw3", 2000L, 3000L);
        assertEquals("CLEAR", review("rw3", 1, 1L).conclusion());

        // 反向：区域 [0,1000)，航线 [1000,2000)
        createRoute("rw4", 1000L, 2000L);
        createHitZone("zw4", 0L, 1000L);
